  1→// Package compact converts full.jsonl transcripts into a normalized,
  2→// compact transcript.jsonl format. Only shared formatting is contained here.
  3→package compact
  4→
  5→import (
  6→	"bufio"
  7→	"bytes"
  8→	"encoding/json"
  9→	"fmt"
 10→	"io"
 11→	"strings"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 14→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 15→)
 16→
 17→// Options provides metadata fields written to every output line.
 18→type Options struct {
 19→	Agent      string // e.g. "claude-code"
 20→	CLIVersion string // e.g. "0.42.0"
 21→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 22→}
 23→
 24→// compactMeta holds pre-computed JSON fragments for fields that are identical
 25→// on every output line, avoiding repeated marshaling.
 26→type compactMeta struct {
 27→	v          json.RawMessage
 28→	agent      json.RawMessage
 29→	cliVersion json.RawMessage
 30→}
 31→
 32→func newCompactMeta(opts Options) compactMeta {
 33→	return compactMeta{
 34→		v:          mustMarshal(1),
 35→		agent:      mustMarshal(opts.Agent),
 36→		cliVersion: mustMarshal(opts.CLIVersion),
 37→	}
 38→}
 39→
 40→// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
 41→//
 42→// The output format puts version, agent, and cli_version on every line,
 43→// flattens the message wrapper, and splits user tool results into separate entries:
 44→//
 45→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 46→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 47→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 48→func Compact(content []byte, opts Options) ([]byte, error) {
 49→	truncated := transcript.SliceFromLine(content, opts.StartLine)
 50→	if truncated == nil {
 51→		truncated = []byte{}
 52→	}
 53→
 54→	if isOpenCodeFormat(truncated) {
 55→		return compactOpenCode(truncated, opts)
 56→	}
 57→
 58→	if isGeminiFormat(truncated) {
 59→		return compactGemini(truncated, opts)
 60→	}
 61→
 62→	if isDroidFormat(truncated) {
 63→		return compactDroid(truncated, opts)
 64→	}
 65→
 66→	return compactJSONL(truncated, opts)
 67→}
 68→
 69→// droppedTypes are JSONL entry types that carry no parser-relevant data.
 70→var droppedTypes = map[string]bool{
 71→	"progress":              true,
 72→	"file-history-snapshot": true,
 73→	"queue-operation":       true,
 74→	"system":                true,
 75→}
 76→
 77→// userAliases maps JSONL type/role values to the canonical "user" kind.
 78→// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
 79→var userAliases = map[string]bool{
 80→	transcript.TypeUser: true,
 81→	"human":             true,
 82→}
 83→
 84→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 85→// JSONL transcript line. It checks the "type" field, then falls back to "role".
 86→// Returns "" for unrecognised or dropped entries.
 87→func normalizeKind(raw map[string]json.RawMessage) string {
 88→	kind := unquote(raw["type"])
 89→	if kind == "" {
 90→		kind = unquote(raw["role"])
 91→	}
 92→
 93→	if droppedTypes[kind] {
 94→		return ""
 95→	}
 96→	if userAliases[kind] {
 97→		return transcript.TypeUser
 98→	}
 99→	if kind == transcript.TypeAssistant {
100→		return transcript.TypeAssistant
101→	}
102→	return ""
103→}
104→
105→// linePreprocessor transforms a parsed JSONL line before conversion.
106→// Used by agent-specific converters to normalize their format (e.g., Droid
107→// envelope unwrapping) before the shared pipeline processes it.
108→type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
109→
110→// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
111→// compact format, one line at a time.
112→func compactJSONL(content []byte, opts Options) ([]byte, error) {
113→	return compactJSONLWith(content, opts, nil)
114→}
115→
116→// compactJSONLWith converts JSONL transcripts into the compact format,
117→// applying an optional per-line preprocessor before conversion.
118→func compactJSONLWith(content []byte, opts Options, preprocess linePreprocessor) ([]byte, error) {
119→	meta := newCompactMeta(opts)
120→	reader := bufio.NewReader(bytes.NewReader(content))
121→	var result []byte
122→
123→	for {
124→		lineBytes, err := reader.ReadBytes('\n')
125→		if err != nil && err != io.EOF {
126→			return nil, fmt.Errorf("reading JSONL line: %w", err)
127→		}
128→
129→		if len(bytes.TrimSpace(lineBytes)) > 0 {
130→			outputLines := convertLine(lineBytes, meta, preprocess)
131→			for _, ol := range outputLines {
132→				result = append(result, ol...)
133→				result = append(result, '\n')
134→			}
135→		}
136→
137→		if err == io.EOF {
138→			break
139→		}
140→	}
141→
142→	return result, nil
143→}
144→
145→// convertLine converts a single JSONL line into zero or more compact transcript lines.
146→func convertLine(lineBytes []byte, meta compactMeta, preprocess linePreprocessor) [][]byte {
147→	var raw map[string]json.RawMessage
148→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
149→		return nil
150→	}
151→
152→	if preprocess != nil {
153→		raw = preprocess(raw)
154→	}
155→
156→	switch normalizeKind(raw) {
157→	case transcript.TypeAssistant:
158→		return convertAssistant(raw, meta)
159→	case transcript.TypeUser:
160→		return convertUser(raw, meta)
161→	default:
162→		return nil
163→	}
164→}
165→
166→func convertAssistant(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
167→	var id, content json.RawMessage
168→	if msg := parseMessage(raw); msg != nil {
169→		id = msg["id"]
170→		if contentRaw, ok := msg["content"]; ok {
171→			content = stripAssistantContent(contentRaw)
172→		}
173→	}
174→
175→	b := marshalOrdered(
176→		"v", meta.v,
177→		"agent", meta.agent,
178→		"cli_version", meta.cliVersion,
179→		"type", mustMarshal(transcript.TypeAssistant),
180→		"ts", raw["timestamp"],
181→		"id", id,
182→		"content", content,
183→	)
184→	return [][]byte{b}
185→}
186→
187→func convertUser(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
188→	var lines [][]byte
189→	ts := raw["timestamp"]
190→
191→	var textContent string
192→	var toolResults []toolResultEntry
193→
194→	if msg := parseMessage(raw); msg != nil {
195→		if contentRaw, ok := msg["content"]; ok {
196→			textContent, toolResults = extractUserContent(contentRaw)
197→		}
198→	}
199→
200→	b := marshalOrdered(
201→		"v", meta.v,
202→		"agent", meta.agent,
203→		"cli_version", meta.cliVersion,
204→		"type", mustMarshal(transcript.TypeUser),
205→		"ts", ts,
206→		"content", mustMarshal(textContent),
207→	)
208→	lines = append(lines, b)
209→
210→	// full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
211→	// When there are multiple tool_result blocks, each user_tool_result line gets the
212→	// same minimized result — a known limitation of the source format.
213→	var minimizedResult json.RawMessage
214→	if turRaw, ok := raw["toolUseResult"]; ok {
215→		minimizedResult = minimizeToolUseResult(turRaw)
216→	}
217→
218→	for _, tr := range toolResults {
219→		result := minimizedResult
220→		if result == nil {
221→			result = mustMarshal(map[string]interface{}{})
222→		}
223→
224→		b := marshalOrdered(
225→			"v", meta.v,
226→			"agent", meta.agent,
227→			"cli_version", meta.cliVersion,
228→			"type", mustMarshal("user_tool_result"),
229→			"ts", ts,
230→			"tool_use_id", mustMarshal(tr.toolUseID),
231→			"result", result,
232→		)
233→		lines = append(lines, b)
234→	}
235→
236→	return lines
237→}
238→
239→type toolResultEntry struct {
240→	toolUseID string
241→}
242→
243→// parseMessage extracts and parses the "message" field from a JSONL transcript
244→// line. All JSONL agents nest content inside a "message" object.
245→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
246→	msgRaw, ok := raw["message"]
247→	if !ok {
248→		return nil
249→	}
250→	var msg map[string]json.RawMessage
251→	if json.Unmarshal(msgRaw, &msg) == nil {
252→		return msg
253→	}
254→	return nil
255→}
256→
257→// extractUserContent separates user message content into text and tool_result entries.
258→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
259→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
260→	var str string
261→	if json.Unmarshal(contentRaw, &str) == nil {
