470→// --- Helpers ---
471→
472→func nonEmptyLines(data []byte) []string {
473→	var lines []string
474→	for _, line := range strings.Split(string(data), "\n") {
475→		if strings.TrimSpace(line) != "" {
476→			lines = append(lines, line)
477→		}
478→	}
479→	return lines
480→}
481→
482→// assertJSONLines compares actual output lines against expected JSON strings,
483→// using semantic JSON equality (order-independent for object keys).
484→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
485→	t.Helper()
486→
487→	actualLines := nonEmptyLines(actual)
488→
489→	if len(expected) == 0 && len(actualLines) == 0 {
490→		return
491→	}
492→
493→	if len(actualLines) != len(expected) {
494→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
495→	}
496→
497→	for i := range expected {
498→		var got, want interface{}
499→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
500→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
501→		}
502→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
503→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
504→		}
505→		if !reflect.DeepEqual(got, want) {
506→			prettyGot, _ := json.MarshalIndent(got, "", "  ")   //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
507→			prettyWant, _ := json.MarshalIndent(want, "", "  ") //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
508→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
509→		}
510→	}
511→}
